{"code":"def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0]) if h else 0
    # 2 marks a full column; 1 and 3 mark full rows. Horizontal lines take precedence at crossings.
    cols=[]; rows=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==2: cols.append(c)
            elif grid[r][c] in (1,3): rows.append((r,grid[r][c]))
    for c in cols:
        for r in range(h):
            if out[r][c]==0: out[r][c]=2
    for r,color in rows:
        for c in range(w): out[r][c]=color
    return out"}

